  static void Bench(Transform r,Vector3 p,float yaw){var g=new GameObject("Boulevard waiting bench").transform;g.SetParent(r,false);g.localPosition=p;g.localRotation=Quaternion.Euler(0,yaw,0);Box(g,"Bench seat",new Vector3(0,.6f,0),new Vector3(3,.16f,.8f),wood,true);Box(g,"Bench back",new Vector3(0,1,.35f),new Vector3(3,.7f,.12f),wood,true);foreach(int s in new[]{-1,1})Box(g,"Bench leg",new Vector3(s*1.1f,.3f,0),new Vector3(.1f,.55f,.7f),bronze,false);}
