  static void Fixture(Transform r,Vector3 p,float width){var go=Box(r,"Boulevard pooled diffuser",p,new Vector3(width,.10f,Mathf.Min(width,.65f)),warm,false);bulbs.Add(go.GetComponent<Renderer>());if(r.name==Layer){float ceiling=0;if(p.x>=550&&p.x<=578&&p.z>=24&&p.z<=69)ceiling=5.13f+Mathf.Sin(Mathf.Clamp01((p.x-555)/22)*Mathf.PI);else if(p.x>=460&&p.x<=524&&p.z>=18&&p.z<=56)ceiling=p.z<28?4.95f:5.7f;else if(p.x>=528&&p.x<=546&&p.z>=31&&p.z<=57)ceiling=5.15f;if(ceiling>p.y)Pipe(r,"Light suspension",p+Vector3.up*.05f,new Vector3(p.x,ceiling,p.z),.025f,bronze);else if(p.y<4)Box(r,"Light fixture support",new Vector3(p.x,p.y*.5f,p.z),new Vector3(.045f,p.y,.045f),bronze,false);}}
