  static void Text(Transform r,string s,Vector3 p,float size,float width,Color c,float yaw=0){var t=new GameObject(s).AddComponent<TextMeshPro>();t.transform.SetParent(r,false);t.transform.localPosition=p;t.transform.localRotation=Quaternion.Euler(0,yaw,0);t.font=TMP_Settings.GetFontAsset();t.text=s;t.fontSize=size*10;t.color=c;t.alignment=TextAlignmentOptions.Center;t.rectTransform.sizeDelta=new Vector2(width,size*4);t.raycastTarget=false;}
  static void Floor(Transform r,string name,Rect a,float y,Material mat){int nx=Mathf.Max(1,Mathf.CeilToInt(a.width/40)),nz=Mathf.Max(1,Mathf.CeilToInt(a.height/40));var v=new List<Vector3>();var t=new List<int>();for(int z=0;z<=nz;z++)for(int x=0;x<=nx;x++)v.Add(new Vector3(Mathf.Lerp(a.xMin,a.xMax,x/(float)nx),y,Mathf.Lerp(a.yMin,a.yMax,z/(float)nz)));for(int z=0;z<nz;z++)for(int x=0;x<nx;x++){int n=z*(nx+1)+x;t.AddRange(new[]{n,n+nx+1,n+1,n+1,n+nx+1,n+nx+2});}var mesh=new Mesh{name=name};mesh.SetVertices(v);mesh.SetTriangles(t,0);mesh.SetUVs(0,v.Select(p=>new Vector2(p.x*.25f,p.z*.25f)).ToList());mesh.RecalculateNormals();var go=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer),typeof(BoxCollider));go.transform.SetParent(r,false);go.GetComponent<MeshFilter>().sharedMesh=mesh;go.GetComponent<Renderer>().sharedMaterial=mat;var b=go.GetComponent<BoxCollider>();b.center=new Vector3(a.center.x,y-.08f,a.center.y);b.size=new Vector3(a.width,.16f,a.height);}
  static GameObject Box(Transform r,string name,Vector3 p,Vector3 s,Material mat,bool solid,PrimitiveType type=PrimitiveType.Cube){var go=GameObject.CreatePrimitive(type);go.name=name;go.transform.SetParent(r,false);go.transform.localPosition=p;go.transform.localScale=s;go.GetComponent<Renderer>().sharedMaterial=mat;UnityEngine.Object.DestroyImmediate(go.GetComponent<Collider>());if(solid)go.AddComponent<BoxCollider>();return go;}
  static void Pipe(Transform r,string name,Vector3 a,Vector3 b,float w,Material mat){var go=Box(r,name,(a+b)*.5f,new Vector3(w,(b-a).magnitude,w),mat,false);go.transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);}
  static Material Load(string folder,string name)=>AssetDatabase.LoadAssetAtPath<Material>(folder+"/"+name+".mat")??throw new InvalidOperationException("Missing "+name);
  static Material Mat(string name,Color c){string p=Folder+"/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(m==null){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,p);}m.color=c;m.enableInstancing=true;m.SetFloat("_Smoothness",.35f);EditorUtility.SetDirty(m);return m;}
  static void Combine(Transform r){int i=0;foreach(var g in r.GetComponentsInChildren<MeshFilter>().Where(f=>f.GetComponent<TMP_Text>()==null&&f.GetComponentInParent<Rigidbody>()==null&&!bulbs.Contains(f.GetComponent<Renderer>())).GroupBy(f=>{var r=f.GetComponent<MeshRenderer>();var p=r.bounds.center;return new{Mat=r.sharedMaterial,X=Mathf.FloorToInt(p.x/40),Z=Mathf.FloorToInt(p.z/40)};}).ToArray()){var mesh=new Mesh{name="Night boulevard "+g.Key.Mat.name,indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(g.Select(f=>new CombineInstance{mesh=f.sharedMesh,transform=r.worldToLocalMatrix*f.transform.localToWorldMatrix}).ToArray(),true,true);string p=Folder+"/Boulevard"+(i++)+".asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(p);if(saved==null){AssetDatabase.CreateAsset(mesh,p);saved=mesh;}else{saved.Clear();EditorUtility.CopySerialized(mesh,saved);saved.UploadMeshData(false);UnityEngine.Object.DestroyImmediate(mesh);}var go=new GameObject(saved.name,typeof(MeshFilter),typeof(MeshRenderer));go.transform.SetParent(r,false);go.GetComponent<MeshFilter>().sharedMesh=saved;go.GetComponent<Renderer>().sharedMaterial=g.Key.Mat;foreach(var f in g){UnityEngine.Object.DestroyImmediate(f.GetComponent<MeshRenderer>());UnityEngine.Object.DestroyImmediate(f);}}}
  static void Register(MotelGameRoot m){var l=m.GetComponentInChildren<WorldNightLighting>();var so=new SerializedObject(l);var intensity=so.FindProperty("intensity");intensity.floatValue=Mathf.Max(intensity.floatValue,8f);var a=so.FindProperty("fixtures");var b=so.FindProperty("glowingSurfaces");int ai=a.arraySize,bi=b.arraySize;a.arraySize+=bulbs.Count;b.arraySize+=bulbs.Count;for(int i=0;i<bulbs.Count;i++){a.GetArrayElementAtIndex(ai+i).objectReferenceValue=bulbs[i].transform;b.GetArrayElementAtIndex(bi+i).objectReferenceValue=bulbs[i];}so.ApplyModifiedPropertiesWithoutUndo();}
